// Posterize-PopArt: kraeftige Saettigung + wenige Farbstufen; die
// Stufenzahl atmet leicht mit dem Bass.
vec4 farbe(vec2 uv, vec4 src)
{
    float grau = dot(src.rgb, vec3(0.299, 0.587, 0.114));
    vec3 satt = mix(vec3(grau), src.rgb, 1.6);
    float stufen = 4.0 + floor(2.0 * bass);
    vec3 ton = floor(clamp(satt, 0.0, 1.0) * stufen + 0.5) / stufen;
    return vec4(ton, 1.0);
}
